INSERT INTO menu_items (id, category, name, description, image_url, price, kind, status, is_archived, sort_order) VALUES
('17000000-0000-4000-8000-000000000001','อาหารจานเดียว','ข้าวกะเพราหมูสับไข่ดาว','กะเพราหมูสับผัดฉ่า หอมใบกะเพรา เสิร์ฟพร้อมไข่ดาวและข้าวสวย',NULL,60.00,'food','available',0,10),
('17000000-0000-4000-8000-000000000002','อาหารจานเดียว','ข้าวกะเพรากุ้ง','กะเพรากุ้งสดผัดพริกสด เผ็ดหอม เสิร์ฟพร้อมข้าวสวย',NULL,90.00,'food','available',0,20),
('17000000-0000-4000-8000-000000000003','อาหารจานเดียว','ข้าวผัดหมู','ข้าวผัดหมูหอมกระทะ เสิร์ฟพร้อมแตงกวาและมะนาว',NULL,55.00,'food','available',0,30),
('17000000-0000-4000-8000-000000000004','อาหารจานเดียว','ข้าวผัดปู','ข้าวผัดเนื้อปูก้อนโต หอมกระทะ เสิร์ฟพร้อมพริกน้ำปลา',NULL,100.00,'food','available',0,40),
('17000000-0000-4000-8000-000000000005','อาหารจานเดียว','ผัดไทยกุ้งสด','เส้นจันท์ผัดซอสมะขาม ใส่กุ้งสด ถั่วงอก กุยช่าย',NULL,80.00,'food','available',0,50),
('17000000-0000-4000-8000-000000000006','อาหารจานเดียว','ราดหน้าหมูนุ่ม','เส้นใหญ่ผัดไหม้ราดน้ำเกรวี่ หมูนุ่ม ผักคะน้า',NULL,65.00,'food','available',0,60),
('17000000-0000-4000-8000-000000000007','อาหารจานเดียว','ข้าวมันไก่ต้ม','ข้าวมันหอม ไก่ต้มนุ่ม เสิร์ฟพร้อมน้ำจิ้มและน้ำซุป',NULL,55.00,'food','available',0,70),
('17000000-0000-4000-8000-000000000008','อาหารจานเดียว','ข้าวหมูกรอบไข่ดาว','หมูกรอบกรอบนอกนุ่มใน เสิร์ฟพร้อมข้าวสวยและไข่ดาว',NULL,70.00,'food','available',0,80),
('17000000-0000-4000-8000-000000000009','กับข้าว','ผัดผักบุ้งไฟแดง','ผักบุ้งสดผัดกระเทียมพริก ไฟแรงหอมกระทะ',NULL,70.00,'food','available',0,10),
('17000000-0000-4000-8000-000000000010','กับข้าว','ไข่เจียวหมูสับ','ไข่เจียวฟูนุ่ม สอดไส้หมูสับ เสิร์ฟร้อนๆ',NULL,50.00,'food','available',0,20),
('17000000-0000-4000-8000-000000000011','กับข้าว','ปลาทอดน้ำปลา','ปลาทับทิมทอดกรอบราดน้ำปลาหอมกระเทียมเจียว',NULL,180.00,'food','available',0,30),
('17000000-0000-4000-8000-000000000012','กับข้าว','หมูทอดกระเทียม','หมูสามชั้นทอดกระเทียมพริกไทย หอมกรอบ',NULL,110.00,'food','available',0,40),
('17000000-0000-4000-8000-000000000013','กับข้าว','แกงจืดเต้าหู้หมูสับ','แกงจืดใสรสกลมกล่อม เต้าหู้อ่อนหมูสับ ผักกาดขาว',NULL,80.00,'food','available',0,50),
('17000000-0000-4000-8000-000000000014','ยำ/ต้ม','ต้มยำกุ้งน้ำใส','ต้มยำน้ำใสรสจัดจ้าน กุ้งสด เห็ดฟาง ตะไคร้ ข่า',NULL,150.00,'food','available',0,10),
('17000000-0000-4000-8000-000000000015','ยำ/ต้ม','ต้มข่าไก่','ต้มข่าไก่น้ำกะทิหอมมัน รสกลมกล่อม',NULL,120.00,'food','available',0,20),
('17000000-0000-4000-8000-000000000016','ยำ/ต้ม','ยำวุ้นเส้นทะเล','ยำวุ้นเส้นรสจัด ใส่กุ้ง หมึก หมูสับ',NULL,120.00,'food','available',0,30),
('17000000-0000-4000-8000-000000000017','ยำ/ต้ม','ส้มตำไทย','ส้มตำมะละกอรสเปรี้ยวหวานเผ็ด ใส่ถั่วลิสงและกุ้งแห้ง',NULL,50.00,'food','available',0,40),
('17000000-0000-4000-8000-000000000018','ของทานเล่น','ไก่ทอดสมุนไพร','ไก่ทอดหมักสมุนไพร กรอบนอกนุ่มใน เสิร์ฟพร้อมน้ำจิ้มแจ่ว',NULL,79.00,'food','available',0,10),
('17000000-0000-4000-8000-000000000019','ของทานเล่น','เฟรนช์ฟรายส์','มันฝรั่งทอดกรอบ โรยเกลือ เสิร์ฟพร้อมซอสมะเขือเทศ',NULL,59.00,'food','available',0,20),
('17000000-0000-4000-8000-000000000020','ของทานเล่น','ปอเปี๊ยะทอด','ปอเปี๊ยะไส้หมูและผัก ทอดกรอบ เสิร์ฟพร้อมน้ำจิ้มบ๊วย',NULL,69.00,'food','available',0,30)
