-- 017_seed_mock_food_menu.sql - PostgreSQL / Supabase edition
-- Mock food menu seed (20 food items + option groups/options for 6 menus).
-- Rerunnable: fixed UUIDs + ON CONFLICT (id) DO UPDATE; touches only 17000000-* rows.

ON CONFLICT (id) DO UPDATE SET category = EXCLUDED.category, name = EXCLUDED.name, description = EXCLUDED.description, image_url = EXCLUDED.image_url, price = EXCLUDED.price, kind = EXCLUDED.kind, status = EXCLUDED.status, is_archived = EXCLUDED.is_archived, sort_order = EXCLUDED.sort_order, updated_at = CURRENT_TIMESTAMP;

ON CONFLICT (id) DO UPDATE SET menu_id = EXCLUDED.menu_id, name = EXCLUDED.name, sort_order = EXCLUDED.sort_order, updated_at = CURRENT_TIMESTAMP;

ON CONFLICT (id) DO UPDATE SET group_id = EXCLUDED.group_id, menu_id = EXCLUDED.menu_id, name = EXCLUDED.name, price_delta = EXCLUDED.price_delta, is_enabled = EXCLUDED.is_enabled, sort_order = EXCLUDED.sort_order, updated_at = CURRENT_TIMESTAMP;
